import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import axios from "axios";

const AdmEditProf = ({ professorId, onClose }) => {
  const [professor, setProfessor] = useState({
    nome: "",
    email: "",
    especialidade: "",
    contacto: "",
  });

  useEffect(() => {
    const fetchProfessor = async () => {
      try {
        const response = await axios.get(`/api/professores/${professorId}`);
        setProfessor(response.data);
      } catch (error) {
        console.error("Erro ao buscar professor:", error);
      }
    };

    fetchProfessor();
  }, [professorId]);

  const handleChange = (e) =>
    setProfessor({ ...professor, [e.target.name]: e.target.value });

  const handleSave = async () => {
    try {
      await axios.put(`/api/professores/${professorId}`, professor);
      alert("Professor atualizado com sucesso!");
      onClose();
    } catch (error) {
      console.error("Erro ao salvar professor:", error);
    }
  };

  return (
    <div className="container mt-4">
      <h2 className="text-center">Editar Professor</h2>

      <div className="mb-3">
        <label className="form-label">Nome</label>
        <input
          type="text"
          className="form-control"
          name="nome"
          value={professor.nome}
          onChange={handleChange}
        />
      </div>

      <div className="mb-3">
        <label className="form-label">Email</label>
        <input
          type="email"
          className="form-control"
          name="email"
          value={professor.email}
          onChange={handleChange}
        />
      </div>

      <div className="mb-3">
        <label className="form-label">Especialidade</label>
        <input
          type="text"
          className="form-control"
          name="especialidade"
          value={professor.especialidade}
          onChange={handleChange}
        />
      </div>

      <div className="mb-3">
        <label className="form-label">Contacto</label>
        <input
          type="text"
          className="form-control"
          name="contacto"
          value={professor.contacto}
          onChange={handleChange}
        />
      </div>

      <div className="d-flex justify-content-between">
        <button className="btn btn-danger" onClick={onClose}>
          Cancelar
        </button>
        <button className="btn btn-primary" onClick={handleSave}>
          Salvar
        </button>
      </div>
    </div>
  );
};

export default AdmEditProf;
